let hasRendered=false;
const appUrl='https://app.mahabbati.com/';
function render(){
 disposeMotion();const t=copy[lang];
 document.documentElement.lang=lang;
 document.title=lang==='id'?'Mahabbati — Berawal dari niat, menuju janji suci':'Mahabbati — Rooted in intention';
 document.querySelector('meta[name="description"]').content=t.heroP;
 const nav=t.nav.map((n,i)=>`<a href="#${['tentang','proses','aplikasi','wedding'][i]}">${n}</a>`).join('');
 document.getElementById('app').innerHTML=`
 <a class="skip" href="#main">${t.skip}</a>
 <header class="site-header"><div class="wrap header"><a href="#" class="wordmark" aria-label="${t.brandHome}"></a><nav class="nav" aria-label="${lang==='id'?'Navigasi utama':'Main navigation'}">${nav}</nav><div class="nav-actions"><div class="language" role="group" aria-label="${lang==='id'?'Pilih bahasa':'Choose language'}"><button data-lang="id" aria-label="Bahasa Indonesia" aria-pressed="${lang==='id'}">ID</button><span aria-hidden="true">/</span><button data-lang="en" aria-label="English" aria-pressed="${lang==='en'}">EN</button></div><a class="header-cta" href="${appUrl}">${t.start}${ico('arrow')}</a><button class="menu-toggle" aria-label="${t.menu}" aria-expanded="false" aria-controls="mobile-nav">${ico('menu')}</button></div></div><nav id="mobile-nav" class="mobile-nav wrap" aria-label="${lang==='id'?'Navigasi seluler':'Mobile navigation'}">${nav}<a href="${appUrl}">${t.start}${ico('arrow')}</a></nav></header>
 <main id="main">
 <section class="hero" aria-labelledby="hero-title"><div class="hero-glow" aria-hidden="true"></div><div class="wrap hero-grid"><div class="hero-copy"><span class="eyebrow">${t.badge}</span><h1 id="hero-title">${t.hero}</h1><div class="hero-bottom"><p>${t.heroP}</p><a class="btn light" href="${appUrl}">${t.start}${ico('arrow')}</a></div></div><div class="hero-art" aria-hidden="true"><img src="assets/jasmine-bloom.png" width="1024" height="1536" alt="" fetchpriority="high"><span class="hero-art-caption">MAHABBATI<br><small>TA’ARUF & WEDDING</small></span></div></div><div class="wrap hero-baseline"><span>${t.note}</span><a href="#tentang">${t.scroll}${ico('arrow')}</a></div></section>
 <div class="trust-bar wrap">${t.trust.map((a,i)=>`<span>${ico(['shield','users','lock'][i])}${a}</span>`).join('')}</div>
 <section id="tentang" class="section wrap about" aria-labelledby="about-title"><div class="section-label"><span>01 / ${t.aboutEye}</span><span class="label-end">MAHABBATI</span></div><div class="intro"><h2 id="about-title">${t.aboutTitle}</h2><p>${t.aboutP}</p></div><div class="feature-grid">${t.features.map((f,i)=>`<article class="feature"><div class="feature-top"><span class="meta">0${i+1}</span><div class="ill ${['verify','privacy','process'][i]}" aria-hidden="true"></div></div><h3>${f[0]}</h3><p>${f[1]}</p></article>`).join('')}</div></section>
 <section id="aplikasi" class="services section wrap" aria-labelledby="app-title"><div class="section-label"><span>02 / ${t.serviceLabel}</span><span class="label-end">TA’ARUF — WALIMAH</span></div><article class="service-row"><div class="app-copy"><span class="eyebrow">${t.appEye}</span><h2 id="app-title">${t.appTitle}</h2><p>${t.appP}</p><ul class="app-benefits">${t.benefits.map(a=>`<li>${ico('check')}${a}</li>`).join('')}</ul><div class="app-buttons"><a class="store-btn" href="https://play.google.com/store/apps/details?id=com.kasministudio.mahabbatimobile">${ico('play')}<span><small>${t.google}</small><strong>Google Play</strong></span></a><a class="text-link" href="${appUrl}">${t.web}${ico('arrow')}</a></div></div><div class="app-art"><div class="panel-topline"><span>MAHABBATI APP</span><span>01</span></div><div class="phone-stage" role="img" aria-label="${t.appAlt}"><div class="phone"></div><div class="phone second"></div></div><div class="panel-caption">${t.caption}</div></div></article>
 <article id="wedding" class="service-row wedding" aria-labelledby="wedding-title"><div class="wedding-copy"><span class="eyebrow">${t.weddingEye}</span><h2 id="wedding-title">${t.weddingTitle}</h2><p>${t.weddingP}</p><div class="wedding-services">${t.weddingServices.map(a=>`<span>${a}${ico('check')}</span>`).join('')}</div><a class="text-link" href="https://wa.me/6282261505350">${t.weddingCta}${ico('arrow')}</a></div><div class="wedding-visual"><div class="panel-topline"><span>MAHABBATI WEDDING</span><span>02</span></div><div class="wedding-image"><img src="assets/hero.png" width="1536" height="1024" alt="${t.altHero}" loading="lazy"></div><div class="panel-caption">${t.weddingArt}</div></div></article></section>
 <section id="proses" class="process-section section" aria-labelledby="process-title"><div class="wrap"><div class="section-label"><span>03 / ${t.processEye}</span><span class="label-end">01 — 06</span></div><div class="process-grid"><div class="process-sticky"><h2 id="process-title">${t.processTitle}</h2><p>${t.processP}</p><div class="bloom-stage" role="img" aria-label="${t.flowerAlt}"><img class="bloom bud" src="assets/jasmine-bud.png" width="1024" height="1536" alt="" loading="lazy"><img class="bloom open" src="assets/jasmine-bloom.png" width="1024" height="1536" alt="" loading="lazy"></div><div class="bloom-caption"><span class="phase-counter" aria-hidden="true">${t.phase} <b>01</b> / 06</span><span>${t.flowerNote}</span></div></div><div class="process-story"><ol class="steps">${t.steps.map((s,i)=>`<li data-step="${i}"><span class="step-num">0${i+1}</span><div><h3>${s[0]}</h3><p>${s[1]}</p></div><span class="step-dot" aria-hidden="true"></span></li>`).join('')}</ol><a class="text-link" href="${appUrl}">${t.processCta}${ico('arrow')}</a></div></div></div></section>
 <section id="faq" class="section wrap faq-section"><div class="section-label"><span>04 / ${t.faqEye}</span><span class="label-end">FAQ</span></div><div class="faq-layout"><div class="faq-intro"><h2>${t.faqTitle}</h2><p>${t.faqP}</p><a class="text-link" href="mailto:salam@mahabbati.com">${t.contact}${ico('arrow')}</a></div><div class="faq-list">${t.faq.map(f=>`<details><summary>${f[0]}${ico('plus')}</summary><p>${f[1]}</p></details>`).join('')}</div></div></section>
 <section class="closing"><div class="wrap closing-grid"><div><span class="eyebrow">${t.badge}</span><h2>${t.closingTitle}</h2><p>${t.closingP}</p><a class="btn light" href="${appUrl}">${t.start}${ico('arrow')}</a></div><div class="closing-mark" aria-hidden="true"></div></div></section></main>
 <footer class="footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand"><a class="wordmark" href="#" aria-label="${t.brandHome}"></a><p>${t.footerP}</p></div><div><h3>${t.explore}</h3><ul>${t.nav.map((n,i)=>`<li><a href="#${['tentang','proses','aplikasi','wedding'][i]}">${n}</a></li>`).join('')}<li><a href="#faq">FAQ</a></li></ul></div><div><h3>${t.help}</h3><ul><li><a href="mailto:salam@mahabbati.com">salam@mahabbati.com</a></li><li><a href="https://instagram.com/mahabbati_official">Instagram${ico('arrow')}</a></li><li><a href="https://wa.me/6282261505350">Wedding organizer${ico('arrow')}</a></li></ul></div><div><h3>${t.location}</h3><p>Jl. Komp. Bappenas Siaga Raya No. 66<br>Pejaten Barat, Jakarta Selatan<br>Indonesia 12510</p></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Mahabbati. ${t.rights}</span><div><a href="https://www.mahabbati.com/terms">${t.privacy}</a><a href="https://www.mahabbati.com/terms">${t.terms}</a></div></div></div></footer>`;
 document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{const y=scrollY;lang=b.dataset.lang;render();document.querySelector(`[data-lang="${lang}"]`).focus({preventScroll:true});scrollTo({top:y,behavior:'instant'});}));
 const toggle=document.querySelector('.menu-toggle'),mobile=document.querySelector('.mobile-nav');
 const close=()=>{toggle.setAttribute('aria-expanded','false');mobile.classList.remove('open');toggle.innerHTML=ico('menu')};
 toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));mobile.classList.toggle('open',open);toggle.innerHTML=ico(open?'close':'menu')});
 mobile.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));
 document.onkeydown=e=>{if(e.key==='Escape'&&mobile.classList.contains('open')){close();toggle.focus()}};
 disposeMotion=setupMotion(!hasRendered);hasRendered=true;
}

function setupMotion(entrance){
 const preference=matchMedia('(prefers-reduced-motion: reduce)');
 const mobile=matchMedia('(max-width: 760px)');
 const running=new Set();let frame=0;let observer;
 const hero=document.querySelector('.hero');
 const process=document.querySelector('.process-section');
 const stage=document.querySelector('.bloom-stage');
 const items=[...document.querySelectorAll('[data-step]')];
 const counter=document.querySelector('.phase-counter b');
 const animate=(el,delay=0,distance=16,duration=700)=>{
  if(preference.matches||!el?.animate)return;
  const a=el.animate([{opacity:0,transform:`translateY(${distance}px)`},{opacity:1,transform:'translateY(0)'}],{duration,delay,easing:'cubic-bezier(.22,1,.36,1)',fill:'backwards'});
  running.add(a);a.onfinish=a.oncancel=()=>running.delete(a);
 };
 if(entrance)[...document.querySelectorAll('.hero-copy > *, .hero-art')].forEach((el,i)=>animate(el,i*80,14,850));
 if('IntersectionObserver'in window){observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){observer.unobserve(e.target);animate(e.target,0,14,650)}}),{threshold:.12});
 document.querySelectorAll('.intro > *, .feature, .app-copy, .app-art, .wedding-copy, .wedding-visual, .faq-layout > *, .closing-grid > div').forEach(el=>{if(entrance||el.getBoundingClientRect().top>innerHeight)observer.observe(el)});}
 const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
 const update=()=>{
  frame=0;
  const h=hero.getBoundingClientRect(),p=process.getBoundingClientRect();
  const rects=items.map(el=>el.getBoundingClientRect());
  const line=innerHeight*(mobile.matches?.58:.48);
  let active=0;rects.forEach((r,i)=>{if(r.top<line)active=i});
  const progress=clamp((line-rects[0].top)/(rects.at(-1).top-rects[0].top||1));
  items.forEach((el,i)=>el.classList.toggle('is-active',i===active));counter.textContent=String(active+1).padStart(2,'0');
  const reduced=preference.matches;
  stage.style.setProperty('--bloom-open',reduced?1:clamp(progress*1.5-.1));
  stage.style.setProperty('--bloom-bud',reduced?0:1-clamp(progress*1.5-.1));
  stage.style.setProperty('--bloom-turn',reduced?'0deg':`${-8+progress*16}deg`);
  stage.style.setProperty('--bloom-rise',reduced?'0px':`${(1-progress)*(mobile.matches?12:28)}px`);
  stage.style.setProperty('--bloom-scale',reduced?'1':String(.94+progress*.08));
  hero.style.setProperty('--hero-drift',reduced?'0px':`${clamp(-h.top/h.height)*-35}px`);
  hero.style.setProperty('--glow-shift',reduced?'0px':`${clamp(-h.top/h.height)*80}px`);
 };
 const schedule=()=>{if(!frame)frame=requestAnimationFrame(update)};
 const onPreference=()=>{if(preference.matches){running.forEach(a=>a.cancel());running.clear()}schedule()};
 const onFocus=()=>running.forEach(a=>a.finish());
 const cleanups=[...document.querySelectorAll('details')].map(el=>{const fn=()=>{if(el.open)animate(el.querySelector('p'),0,5,250)};el.addEventListener('toggle',fn);return()=>el.removeEventListener('toggle',fn)});
 addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);preference.addEventListener('change',onPreference);document.addEventListener('focusin',onFocus);schedule();
 return()=>{observer?.disconnect();cancelAnimationFrame(frame);running.forEach(a=>a.cancel());cleanups.forEach(f=>f());removeEventListener('scroll',schedule);removeEventListener('resize',schedule);preference.removeEventListener('change',onPreference);document.removeEventListener('focusin',onFocus)};
}
render();
